        'descriptions' => 'SELECT custom_field_id,language_id,name FROM `' . $p . 'custom_field_description` ORDER BY custom_field_id,language_id LIMIT 1025',
        'groups' => 'SELECT custom_field_id,customer_group_id,`required` FROM `' . $p . 'custom_field_customer_group` ORDER BY custom_field_id,customer_group_id LIMIT 1025',
        'customer_groups' => 'SELECT customer_group_id FROM `' . $p . 'customer_group` ORDER BY customer_group_id LIMIT 17',
        'languages' => 'SELECT language_id,code,status FROM `' . $p . 'language` ORDER BY language_id LIMIT 17',
        'mapping' => 'SELECT setting_id,store_id,code,`key`,value,serialized FROM `' . $p . 'setting` WHERE code=\'bs_account_profile\' OR `key`=\'bs_account_profile_map\' ORDER BY setting_id LIMIT 3'
