    return $out;
}
function ar_registry_schema(mysqli $db, string $p): void {
    // INFORMATION_SCHEMA hides trigger rows without TRIGGER visibility. Refuse
    // to infer absence from a privilege-filtered empty result.
    $database=acc009a_rows($db,'SELECT DATABASE() AS name',1);$database=$database[0]['name']??'';
    $grants=acc009a_rows($db,'SHOW GRANTS FOR CURRENT_USER()',16);$visible=false;
    foreach ($grants as $grant) {
        $line=(string)reset($grant);$line=str_replace(['\\_','\\%'],['_','%'],$line);
        if (!preg_match('/^GRANT (.+) ON (\S+) TO /iD',$line,$m)) continue;
        if (!in_array($m[2],['*.*','`'.$database.'`.*'],true)) continue;
        if (preg_match('/(?:^|, )(?:ALL PRIVILEGES|TRIGGER)(?:,|$)/iD',$m[1])) $visible=true;
    }
    ar_assert($visible,'trigger_visibility_privilege_required');
    $required = ['custom_field'=>['custom_field_id','type','value','validation','location','status','sort_order'],
        'custom_field_description'=>['custom_field_id','language_id','name'],
        'custom_field_customer_group'=>['custom_field_id','customer_group_id','required'],
        'setting'=>['setting_id','store_id','code','key','value','serialized']];
    foreach ($required as $table => $columns) {
        $name = $db->real_escape_string($p . $table);
        $engine = acc009a_rows($db, "SELECT ENGINE AS engine FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='" . $name . "'", 1);
        ar_assert(count($engine) === 1 && strtoupper($engine[0]['engine']) === 'INNODB', 'transactional_registry_required:' . $table);
        $rows = acc009a_rows($db, "SELECT COLUMN_NAME AS field FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='" . $name . "' ORDER BY ORDINAL_POSITION LIMIT 65", 64);
        ar_assert(!array_diff($columns, array_column($rows, 'field')), 'registry_schema_changed:' . $table);
        $triggers = acc009a_rows($db, "SELECT TRIGGER_NAME AS name FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='" . $name . "' LIMIT 2", 1);
        ar_assert($triggers === [], 'registry_trigger_requires_review:' . $table);
    }
}
function ar_metadata(mysqli $db, string $p, array $s): array {
