    $events = array_values(array_filter($events, static function($r) { return (bool)$r['status']; }));
    $normalize = static function($e) { return ['code'=>$e['code'],'trigger'=>$e['trigger'],'action'=>$e['action'],'status'=>(int)$e['status'],'sort_order'=>(int)$e['sort_order']]; };
    $events = array_map($normalize, $events);
