    $sort($events); $expected = array_map($normalize, $s['events']); $sort($expected);
    ar_assert($events === $expected, 'active_events_changed');
    // Overrides in either table require explicit source composition review. Theme
    // in OC4 has no universal status column; do not invent its schema.
