        $rows = acc009a_rows($db, 'SELECT COUNT(*) AS total FROM `' . $p . $table . '`', 1);
        ar_assert(count($rows) === 1 && (int)$rows[0]['total'] === 0, $table . '_override_requires_review');
    }
