            ar_assert(++$seen<=40000,'catalog_reader_count_cap');ar_assert(!$f->isLink(),'linked_catalog_reader');
            $rel=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));
            if (!preg_match('~^(?:catalog|extension/[^/]+/catalog)/(?:controller|model|view)/.+\.(?:php|twig|js)$~D',$rel) || !$f->isFile()) continue;
            ar_assert($f->getSize()<=2000000,'catalog_reader_size_cap');
            // Conservatively include both unchanged H1 protected dependencies
            // by exact identity, without classifying or reading their raw bodies.
            if (in_array($rel,['catalog/model/checkout/order.php','extension/telegram_notify/catalog/controller/event/telegram.php'],true)) {
                $found[$rel]=hash_file('sha256',$f->getPathname());continue;
            }
            $body=file_get_contents($f->getPathname());$bytes+=strlen($body);
            ar_assert($bytes<=100000000,'catalog_reader_bytes_cap');
            if(preg_match('/(?:custom_field|getCustomFields\s*\(|getCustomField\s*\()/i',$body))$found[$rel]=hash('sha256',$body);
        }
    }
    ksort($found);return $found;
}
function ar_customer_callers(string $root): array {
    $found = []; $seen = 0; $total = 0;
    foreach (['adminEvhenii/controller','adminEvhenii/model','adminEvhenii/view/template','adminEvhenii/view/javascript','extension'] as $relative) {
        $dir = acc009a_path($root,$relative); if (!is_dir($dir)) continue;
        $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
        foreach ($it as $f) {
            if (++$seen > 30000) acc009a_fail('caller_inventory_cap');
            if ($f->isLink()) acc009a_fail('linked_caller_inventory');
            $rel = str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));
            if ($relative === 'extension' && !preg_match('~^extension/[^/]+/admin/(controller|model|view/(template|javascript))/~',$rel)) continue;
            if (!$f->isFile() || !preg_match('/\.(php|twig|js)$/D',$rel)) continue;
            ar_assert($f->getSize() <= 2000000, 'caller_source_size_cap');
            $body = file_get_contents($f->getPathname()); $total += strlen($body);
            ar_assert($total <= 80000000, 'caller_inventory_bytes_cap');
            if (preg_match('/(?:->getCustomers\s*\(|customer\/customer\.autocomplete)/',$body)) $found[$rel] = hash('sha256',$body);
        }
    }
    ksort($found);return $found;
}
function ar_targets(string $root, array $s, bool $allowAfter = false): array {
    $out = []; $states = [];
    foreach ($s['files'] as $rel => $row) {
        $path = acc009a_path($root,$rel);
        ar_assert(!is_link($path), 'linked_target');
        ar_assert(!file_exists($path) || is_file($path), 'nonregular_target');
        ar_assert(!is_file($path) || filesize($path)<=4000000, 'target_size_cap');
        $body = is_file($path) ? file_get_contents($path) : null;
        $hash = $body === null ? null : hash('sha256',$body);
        ar_assert($hash === $row['before'] || ($allowAfter && $hash === $row['after']), 'target_hash_changed:' . $rel);
        $states[] = $hash === $row['after'] ? 'after' : 'before';
        $out[$rel] = ['path'=>$path,'body'=>$body,'hash'=>$hash];
    }
    ar_assert(count(array_unique($states)) <= 1, 'partial_application_STOP');
    return $out;
}
function ar_admit(string $root, array $s): array {
