    ar_assert($found === $expected, 'customer_caller_inventory_changed');
    $expected=$s['catalog_readers'];ksort($expected);
    ar_assert(ar_catalog_readers($root)===$expected,'catalog_reader_inventory_changed');
    $c = acc009a_config($root);
    ar_assert(($c['DIR_CACHE']??'')==='/home2/boosters/ocartdata/storage/cache/' && ($c['DIR_STORAGE']??'')==='/home2/boosters/ocartdata/storage/','configured_cache_path_changed');
    $db = ar_db($c);
