    finally { $db->close(); }
    $already = false;
    if ($snapshot['mapping'] !== []) {
        ar_assert($s['kind'] === 'metadata' && count($snapshot['mapping']) === 1, 'metadata_already_active_or_collision');
        $row=$snapshot['mapping'][0];$m=json_decode($row['value'],true,32,JSON_THROW_ON_ERROR);
        ar_assert($row['code']==='bs_account_profile' && $row['key']==='bs_account_profile_map' && (int)$row['store_id']===0 && (int)$row['serialized']===1
            && ($m['runner_sha256']??'')===hash_file('sha256',__FILE__)
            && preg_match('/^ACC-009-WP3c-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}$/D',$m['backup_name']??'')===1,'mapping_collision_STOP');
        $owned=dirname($root).'/_patch_backups/'.$m['backup_name'];acc009r_abs($owned);acc009r_abs($owned.'/manifest.json');
        $journal=json_decode(file_get_contents($owned.'/manifest.json'),true,64,JSON_THROW_ON_ERROR);
        ar_assert(($journal['task']??'')===$s['id'] && ($journal['state']??'')==='committed'
            && ar_hash($journal['after']??null)===ar_hash($snapshot),'owned_metadata_state_drift_STOP');
        $already=true;
    }
    // New IDs are never guessed; the old registry must remain disabled and unchanged.
    if (!$already) {
        ar_assert(count($snapshot['fields']) === 27, 'unexpected_registry_count');
        foreach ($snapshot['fields'] as $f) ar_assert((int)$f['status'] === 0, 'existing_field_activated');
    }
    $runtime = acc009r_web($root);
    ar_assert($runtime === ['php'=>'8.0.30','sapi'=>'litespeed','opcache_enabled'=>true,'validate_timestamps'=>true,'revalidate_freq'=>2], 'web_runtime_changed');
    return ['metadata'=>$snapshot,'metadata_sha256'=>ar_hash($snapshot),'runtime'=>$runtime,'probe_cleanup'=>'ok','already_applied'=>$already,'sender_identity_unchanged'=>$s['id']!=='ACC-009-WP3b'];
}
function ar_backup(string $root, array $s, array $data): string {
    $parent = dirname($root) . '/_patch_backups'; acc009r_abs($parent);
    $dir = $parent . '/' . $s['id'] . '-' . gmdate('Ymd\THis\Z') . '-' . bin2hex(random_bytes(4));
    ar_assert(mkdir($dir,0700), 'backup_create_failed'); acc009r_abs($dir);
    ar_assert(file_put_contents($dir.'/manifest.json',ar_json($data),LOCK_EX) !== false, 'backup_manifest_failed');
    return $dir;
}
function ar_replace(string $path, ?string $beforeHash, string $body, int $mode): void {
    $current = is_file($path) ? hash_file('sha256',$path) : null;
    ar_assert(!is_link($path) && $current === $beforeHash,'target_changed_before_write');
    $temp = $path . '.acc009-' . bin2hex(random_bytes(8)); $h = fopen($temp,'x');
    ar_assert($h !== false,'target_temp_failed');
    try {
        ar_assert(fwrite($h,$body) === strlen($body) && fflush($h),'target_temp_write_failed');
        ar_assert(fclose($h),'target_temp_close_failed'); $h = null;
        ar_assert(chmod($temp,$mode),'target_temp_mode_failed');
        ar_assert(!is_link($path) && (is_file($path)?hash_file('sha256',$path):null) === $beforeHash,'target_changed_before_rename');
        ar_assert(rename($temp,$path),'target_rename_failed');
    } finally { if (is_resource($h)) fclose($h); if (is_file($temp)) unlink($temp); }
}
function ar_source_apply(string $root, array $s, array $targets): array {
    $manifest = ['schema'=>'acc009.source-backup.v1','task'=>$s['id'],'files'=>[]];
    foreach ($s['files'] as $rel=>$r) $manifest['files'][$rel] = ['before'=>$r['before'],'after'=>$r['after'],'mode'=>$r['before']===null?0644:(fileperms($targets[$rel]['path']) & 0777)];
    $backup = ar_backup($root,$s,$manifest); $changed = []; $i = 0;
    foreach ($targets as $rel=>$v) {
        if ($v['body'] !== null) ar_assert(file_put_contents($backup.'/'.$i.'.source',$v['body'],LOCK_EX) === strlen($v['body']),'backup_write_failed');
        $i++;
    }
    try {
        foreach ($s['files'] as $rel=>$r) {
            $body = base64_decode($r['body_b64'],true);ar_assert(is_string($body) && hash('sha256',$body)===$r['after'],'payload_hash_failed');
            if (substr($rel,-4)==='.php') acc009s_lint_payload($body);
            $path=$targets[$rel]['path']; $parent=dirname($path);acc009r_abs($parent);
            ar_replace($path,$r['before'],$body,$manifest['files'][$rel]['mode']);$changed[]=$rel;
            if (substr($rel,-4)==='.php') acc009s_lint($path);
            ar_assert(hash_file('sha256',$path)===$r['after'],'post_write_hash_failed');
        }
    } catch (Throwable $e) {
        foreach (array_reverse($changed) as $rel) {
            $path=$targets[$rel]['path'];ar_assert(hash_file('sha256',$path)===$s['files'][$rel]['after'],'recovery_drift_STOP');
            if ($targets[$rel]['body'] === null) ar_assert(unlink($path),'recovery_unlink_failed');
            else ar_replace($path,$s['files'][$rel]['after'],$targets[$rel]['body'],$manifest['files'][$rel]['mode']);
        }
        acc009a_fail('source_apply_failed_originals_restored');
    }
    return ['backup'=>$backup,'changed_files'=>count($changed),'action'=>'applied'];
}
function ar_source_rollback(string $root,array $s,string $name,bool $check): array {
    ar_assert(preg_match('/^'.preg_quote($s['id'],'/').'-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}$/D',$name)===1,'invalid_exact_backup_name');
    $dir=dirname($root).'/_patch_backups/'.$name;acc009r_abs($dir);acc009r_abs($dir.'/manifest.json');
    $m=json_decode(file_get_contents($dir.'/manifest.json'),true,64,JSON_THROW_ON_ERROR);
    ar_assert(($m['schema']??'')==='acc009.source-backup.v1' && ($m['task']??'')===$s['id'] && array_keys($m['files']??[])===array_keys($s['files']),'backup_manifest_mismatch');
    if ($s['id']==='ACC-009-WP3b') ar_assert(!file_exists($root.'/catalog/view/javascript/booster-account-universal.js'),'rollback_N2_before_WP3b');
    $c=acc009a_config($root);$db=ar_db($c);
    try {$row=acc009a_rows($db,"SELECT setting_id FROM `".$c['DB_PREFIX']."setting` WHERE code='bs_account_profile' OR `key`='bs_account_profile_map' LIMIT 3",2);ar_assert($row===[],'rollback_metadata_first');}
    finally {$db->close();}
    $plan=[];$i=0;
    foreach ($s['files'] as $rel=>$r) {
        $meta=$m['files'][$rel];ar_assert($meta['before']===$r['before'] && $meta['after']===$r['after'],'backup_row_identity');
        $path=acc009a_path($root,$rel);$hash=is_file($path)?hash_file('sha256',$path):null;
        ar_assert($hash===$r['before'] || $hash===$r['after'],'rollback_target_drift_STOP');
        $body=null;
        if ($r['before']!==null) {
            $file=$dir.'/'.$i.'.source';acc009r_abs($file);ar_assert(is_file($file) && hash_file('sha256',$file)===$r['before'],'rollback_backup_hash_failed');$body=file_get_contents($file);
        }
        ar_assert(is_int($meta['mode']) && $meta['mode']>=0 && $meta['mode']<=0777,'backup_mode_invalid');
        $plan[$rel]=['path'=>$path,'hash'=>$hash,'body'=>$body,'mode'=>$meta['mode']];$i++;
    }
    if (!$check) foreach (array_reverse($plan,true) as $rel=>$r) {
        if ($r['hash']===$s['files'][$rel]['before']) continue;
        if ($r['body']===null) {ar_assert(hash_file('sha256',$r['path'])===$r['hash'] && unlink($r['path']),'rollback_remove_failed_STOP');}
        else {ar_replace($r['path'],$r['hash'],$r['body'],$r['mode']);if(substr($rel,-4)==='.php')acc009s_lint($r['path']);}
    }
    return ['action'=>$check?'rollback_planned':'restored','backup'=>$dir,'changed_files'=>$check?0:count($plan)];
}
function ar_authority(string $encoded, array $admission): array {
